create or replace function public.claim_prepaid_order_cancellation(p_order_id bigint, p_user_id uuid, p_reason text, p_refund_amount numeric) returns public.orders language plpgsql security definer set search_path to 'pg_catalog', 'public' as $function$ declare o public.orders%rowtype; begin if current_user not in ('service_role','postgres') then raise exception 'service role required'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null or char_length(trim(p_reason)) > 180 then raise exception 'Invalid cancellation reason'; end if; if p_refund_amount is null or p_refund_amount <= 0 then raise exception 'Invalid refund amount'; end if; select * into o from public.orders where id=p_order_id and user_id=p_user_id for update; if not found then raise exception 'Order not found'; end if; if o.payment_method <> 'prepaid' or o.status <> 'paid' then raise exception 'This prepaid order is not in a cancellable payment state'; end if; if coalesce(o.fulfillment_status,'ordered') not in ('ordered','packed') then raise exception 'This order can no longer be cancelled because fulfilment has progressed'; end if; update public.orders set status='refund_initiated', fulfillment_status='cancelled', fulfillment_updated_at=now(), cancellation_reason=trim(p_reason), cancelled_at=now(), refund_amount=p_refund_amount, refund_status='requested', refund_updated_at=now() where id=o.id returning * into o; return o; end; $function$; revoke all on function public.claim_prepaid_order_cancellation(bigint,uuid,text,numeric) from public, anon, authenticated; grant execute on function public.claim_prepaid_order_cancellation(bigint,uuid,text,numeric) to service_role;